
import { NextRequest, NextResponse } from 'next/server';
import { generateGeminiResponse } from '@/lib/gemini';

export async function POST(request: NextRequest) {
  try {
    // Nhận dữ liệu từ Website
    const body = await request.json();
    const { prompt } = body;

    // Kiểm tra dữ liệu đầu vào
    if (!prompt || typeof prompt !== 'string') {
      return NextResponse.json(
        { success: false, message: 'Vui lòng nhập nhu cầu tư vấn quà Tết.' },
        { status: 400 }
      );
    }

    if (prompt.length > 3000) {
      return NextResponse.json(
        { success: false, message: 'Nội dung yêu cầu quá dài.' },
        { status: 400 }
      );
    }

    // Xây dựng yêu cầu tư vấn
    const aiPrompt = `
      Bạn là chuyên gia tư vấn quà Tết của website Elegift.

      Hãy phân tích nhu cầu khách hàng và tư vấn quà Tết phù hợp.

      Yêu cầu:
      - Xác định đối tượng nhận quà.
      - Phân tích ngân sách.
      - Đề xuất loại quà phù hợp.
      - Giải thích lý do lựa chọn.
      - Trả lời bằng tiếng Việt, rõ ràng và thân thiện.
      - Không tự bịa tên sản phẩm, giá bán hoặc thông tin tồn kho.

      Nhu cầu khách hàng:
      ${prompt}
    `;

    // Gọi Gemini API
    const result = await generateGeminiResponse(aiPrompt);

    // Trả kết quả về Website
    return NextResponse.json({
      success: true,
      data: {
        recommendation: result,
      },
    });

  } catch (error) {
    console.error('AI Recommendation API Error:', error);

    return NextResponse.json(
      {
        success: false,
        message: 'Không thể thực hiện tư vấn AI. Vui lòng thử lại.',
      },
      { status: 500 }
    );
  }
}
